"""Read and score the binding left by a completed ordinary question.

No answer is decoded from a numeral, an address's magnitude or a nearest
numeric class. Text targets are consulted only after the candidate is fixed.
"""
import torch

from ThoughtReferences import bindings, open_slots


def references(meaning):
    if open_slots(meaning):
        return ()
    roles = [role for kind, role in bindings(meaning).get('_bound_roles', ())
             if kind == 'referent']
    return tuple((meaning.role_refs[role], meaning.roles[role]) for role in roles
                 if meaning.role_refs[role] is not None)


def _bound_references(meaning):
    roles = [role for kind, role in bindings(meaning).get('_bound_roles', ())
             if kind == 'referent']
    return tuple((meaning.role_refs[role], meaning.roles[role]) for role in roles
                 if meaning.role_refs[role] is not None)


def matches(model, meaning, word):
    """Strict identity match against the existing lexical association index."""
    return _matches(model, meaning, word, references(meaning))


def _matches(model, meaning, word, values):
    known = set(model._concept_owner().word_concepts(word))
    if len(values) != 1 or not known:
        return False
    reference, _value = values[0]
    store = getattr(model.symbolSpace, 'ltm_store', None)
    seen = set()
    current = meaning
    for _ in range(64):
        if reference in seen:
            return False
        seen.add(reference)
        if reference[0] == 'sym':
            if reference[1] in known:
                return True
            if store is None or not store.parts.contains(reference[1]):
                return False
            from PartRead import expression_components
            from QueryWork import QueryWorkBudget
            terms, _, incomplete = expression_components(store, (reference,),
                max_records=64, work=QueryWorkBudget(64))
            target = terms.get(reference, {}).get('head_reference')
            if incomplete or target is None or target == reference:
                return False
            reference = target
            continue
        if reference[0] == 'constituent':
            current = current.constituents[reference[1]]
        elif reference[0] == 'ltm' and store is not None:
            index = store._index_occurrences.get(reference)
            if index is None:
                return False
            if int(store.row_ids[index]) in known:
                return True
            current = store.meaning_of(index)
        else:
            return False
        if current is None or int(current.role_mask.sum()) != 1:
            return False
        role = int(current.role_mask.nonzero(as_tuple=False)[0])
        reference = current.role_refs[role]
        if reference is None:
            return False
    return False


def cost(model, meaning, target, *, stream=0):
    """An exact bound identity costs zero; other bindings receive code error.

    This is a loss-side answer term for the existing paired chooser rule.
    Missing target identities or an unbound answer cannot be scored as correct.
    """
    # R + A judges the answer's referent, irrespective of the evidence pair
    # or another still-free role. The committed-row verifier above is unchanged.
    values = _bound_references(meaning)
    if _matches(model, meaning, target, values):
        return meaning.roles.new_zeros(())
    if len(values) != 1:
        return meaning.roles.new_ones(())
    owner = model._concept_owner()
    rows = [owner._csw_row_of(identity) for identity in owner.word_concepts(target)]
    rows = [row for row in rows if row is not None]
    if not rows:
        return meaning.roles.new_ones(())
    basis = owner.similarity_codebook.lookup_rows(torch.tensor(
        rows, device=meaning.roles.device, dtype=torch.long),stream=stream).detach()
    distance = (basis - values[0][1].detach()).square().mean(-1).min()
    return .5 + .5 * distance / (1 + distance)

def _capture_reading_programs(self, sentence_slot=None, *, admit=True):
    """Capture one program per sentence, sharing final rows with their slot.

    This is the eager boundary after forward publication. The whole brick's
    indexed leaves are gathered once, then copied into compact per-row
    records. A packed row with no sentence in a slot contributes None.
    """
    if getattr(self, '_open_sentence_slot', None) is None:
        raise RuntimeError('operation records exist only while a sentence is open')
    reference = getattr(self, "_tensor_pushed_ideas", None)
    isp = getattr(self, "inputSpace", None)
    active = getattr(isp, "_word_active_mask", None)
    if (not torch.is_tensor(reference) or reference.dim() != 3
            or not torch.is_tensor(active)
            or tuple(active.shape) != tuple(reference.shape[:2])):
        return (), {}
    B, W, D = reference.shape
    rows = self._word_symbol_rows()
    if not torch.is_tensor(rows) or tuple(rows.shape) != (B, W):
        rows = torch.full((B, W), -1, dtype=torch.long, device=reference.device)
    word_rows = getattr(isp, "_ar_word_concept_rows", None)
    if not torch.is_tensor(word_rows) or tuple(word_rows.shape) != (B, W):
        word_rows = torch.full_like(rows, -1)
    concept_ids = self._word_symbol_concept_ids()
    if not torch.is_tensor(concept_ids) or concept_ids.shape != rows.shape:
        concept_ids = torch.full_like(rows, -1)
    # The mixing reader stages admitted OBJECT identities beside the
    # same grammar atoms that _pushed_word_slab consumes. Its WORD lane
    # is intentionally absent; that does not make these objects unknown.
    # These are references for the close, not WORD interpretation inputs.
    grammar_rows = getattr(isp, '_ar_grammar_object_rows', None)
    grammar_ids = getattr(isp, '_ar_grammar_object_ids', None)
    if (torch.is_tensor(grammar_rows) and torch.is_tensor(grammar_ids)
            and grammar_rows.shape == rows.shape and grammar_ids.shape == rows.shape):
        if grammar_ids.dtype != torch.long:
            raise TypeError('grammar OBJECT identities must use integer address tensors')
        concept_ids = torch.where(grammar_rows.to(rows.device) >= 0,
            grammar_ids.to(rows.device), concept_ids)
    activations = getattr(self.symbolSpace, "_word_reference_presences", None)
    if not torch.is_tensor(activations):
        activations = reference.new_ones(B, W)
    else:
        if activations.shape != (B, W, 1):
            raise ValueError('word reference presences must align with the current [B,W,1] shape')
        activations = activations.reshape(B, W)
    leaves = self._answer_leaf_slab(rows)
    lexical_forms = self._word_lexical_forms(B, W)
    ids = getattr(isp, "_packed_sentence_ids", None)
    packed = (bool(getattr(isp, "_sentence_pack_enabled", False))
              and torch.is_tensor(ids) and tuple(ids.shape) == (B, W))
    if packed:
        active = active.to(torch.bool)
        slots = sorted(int(t) for t in ids[active].unique().tolist() if int(t) >= 0)
        positions = torch.arange(W, device=active.device).expand(B, W)
        last = torch.where(active, positions, -1).amax(dim=1)
        last_ids = ids.gather(1, last.clamp_min(0)[:, None]).squeeze(1)
        last_ids = torch.where(last >= 0, last_ids, -1).tolist()
    else:
        slots, last_ids = [0], [0] * B
    captured = {}
    if sentence_slot is not None:
        slots = [sentence_slot]
    bank = getattr(self, "_tensor_sentence_roots_live", None)
    for slot in slots:
        if sentence_slot is None and slot in captured:
            continue
        program = self._derivation_program(slot if packed else None)
        if packed or sentence_slot is not None:
            end = (bank[:, slot].reshape(B, 3, D)
                   if torch.is_tensor(bank) and bank.dim() == 3
                   and slot < bank.shape[1] and bank.shape[-1] == 3 * D
                   else None)
        else:
            end = self._sentence_end_state(None)
        captured[slot] = (
            self._program_entries(program, leaves, rows, word_rows, activations, end,
                                  concept_ids=concept_ids,
                                  lexical_forms=lexical_forms, admit=admit)
            if program is not None and torch.is_tensor(end)
            else (None,) * B)
    current = tuple(captured.get(int(t), (None,) * B)[b]
                    for b, t in enumerate(last_ids))
    return current, captured

